function demo(x) {
  if (true) {
    var a = 1;
    let b = 2;
  }
  console.log(a); // 1
  console.log(b); // ReferenceError
}

const x = 'global';
function outer() {
  const x = 'outer';
  function inner() {
    console.log(x); // 'outer' — lexical, not caller
  }
  return inner;
}
const fn = outer();
fn();

const user = { name: 'Ada' };
user.name = 'Grace'; // OK — mutation
// user = {}; // TypeError — rebinding

function f(a = b, b = 2) {
  return a + b;
}
f(); // ReferenceError: Cannot access 'b' before initialization

try {
  throw new Error('boom');
} catch (err) {
  console.log(err.message);
}
// console.log(err); // ReferenceError outside catch
